typedef float time_value_t;
typedef float vm_num_t;

class vm_stack
{
public:
  bool push(const char* src, int n);
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t
    {
      FIRST_ENTRY,
      RECALL_ENTRY
    };

    virtual bool operator()(vm_stack& stack, entry_t entry) { return true; }
  };
};

class world_dynamics_system
{
public:
  time_value_t get_cur_time_inc() const;
};

extern world_dynamics_system* g_world_ptr;
void error(const char* message);

#define TARGET_MKS
#define SLF_RETURN \
  if (!stack.push((char*)&result,sizeof(result)) ) \
    error( "script stack overflow" )
#define SLF_DONE \
  return true

class slf_get_cur_time_inc_t : public script_library_class::function
{
  public:
    virtual bool operator()(vm_stack& stack,entry_t entry)
    {
      vm_num_t result = g_world_ptr->get_cur_time_inc();
      SLF_RETURN;
      SLF_DONE;
    }
};
